    if (k.step === 1) return head + '<div class="portal" style="padding:14px"><p style="font-weight:700;margin-bottom:8px">' + (es ? "El año pasado nos envió:" : "Last year you sent us:") + '</p><div class="row" style="gap:6px;flex-wrap:wrap;margin-bottom:16px">' + k.last.map((x) => '<span class="chip">' + esc(nm(x)) + "</span>").join("") + '</div><p style="margin-bottom:12px">' + (es ? "¿" + e.year + " fue más o menos igual?" : "Was " + e.year + " about the same?") + '</p><button class="btn pri" style="width:100%;justify-content:center;margin-bottom:8px" data-a="ckSame">' + (es ? "Sí, más o menos igual" : "Yes, about the same") + '</button><button class="btn" style="width:100%;justify-content:center" data-a="ckNext">' + (es ? "Algunas cosas cambiaron" : "Some things changed") + "</button></div>";
    return head + '<div class="portal" style="padding:12px 14px"><p style="font-weight:700">' + (es ? "¿Qué tuvo en " + e.year + "?" : "What did you have in " + e.year + "?") + '</p><p class="small muted" style="margin:2px 0 10px">' + (es ? "Toque todo lo que aplica. Quite lo que ya no." : "Tap everything that applies. Untap anything that no longer does.") + '</p><div class="tiles">' + T.CHECKQ.map((q) => '<button class="tile' + (k.facts[q[0]] ? " on" : "") + '" data-a="ckTap" data-k="' + q[0] + '" aria-pressed="' + (k.facts[q[0]] ? "true" : "false") + '">' + esc(es ? q[2] : q[1]) + "</button>").join("") + '<button class="tile' + (k.other ? " on" : "") + '" data-a="ckOther" aria-pressed="' + (k.other ? "true" : "false") + '" style="grid-column:1/-1;min-height:44px">' + (es ? "Algo más que no está aquí" : "Something else not listed here") + "</button></div>" +
      (k.facts.w2 ? '<div class="row" style="margin-top:12px;flex-wrap:nowrap"><span class="grow small">' + (es ? "¿Cuántos empleadores?" : "How many employers?") + '</span><button class="btn sm" data-a="ckW2" data-d="-1" aria-label="Fewer">&minus;</button><b style="min-width:20px;text-align:center">' + k.w2 + '</b><button class="btn sm" data-a="ckW2" data-d="1" aria-label="More">+</button></div>' : "") +
      '<textarea id="ckNote" maxlength="300" placeholder="' + (k.other ? (es ? "¿Qué más? Unas palabras bastan" : "What else? A few words is enough") : es ? "¿Algo más que debamos saber? (opcional)" : "Anything else we should know? (optional)") + '" style="margin-top:12px;min-height:54px' + (k.needNote ? ";border-color:var(--bad)" : "") + '">' + esc(k.note) + "</textarea>" + (k.needNote ? '<div class="small" style="color:var(--bad);margin-top:4px">' + (es ? "Cuéntenos en unas palabras." : "Tell us in a few words.") + "</div>" : "") + '<button class="btn pri" style="margin-top:12px;width:100%;justify-content:center" data-a="' + (ckWho(k).length ? "ckWhoGo" : "ckSend") + '"' + (k.busy ? " disabled" : "") + ">" + (k.busy ? (es ? "Enviando..." : "Sending...") : ckWho(k).length ? (es ? "Siguiente" : "Next") : es ? "Enviar" : "Send") + "</button></div>";
