    const prompt = kind === "text" ? "You read text messages from a tax client to their accounting firm's document-collection assistant. Classify the message. Answer with JSON only: {\"intent\": one of \"stop\",\"start\",\"help\",\"yes\",\"no\",\"where_to_find\",\"status\",\"says_none\",\"will_send_later\",\"thanks\",\"question\",\"other_update\", \"item_id\": the id of the document they mean from the list, or null, \"later_days\": number of days if they say when they will send it, or null, \"summary\": a plain summary in under 12 words, \"scope\": one of \"documents\",\"tax_question\",\"billing\",\"scheduling\",\"personal\",\"complaint\",\"other\" (documents means sending, finding or timing documents), \"sentiment\": one of \"calm\",\"confused\",\"frustrated\",\"upset\", \"topics\": a list of zero or more of these keys, only for things the client says about their own year that the firm may not know yet: " + topicKeys() + " (empty list if none; never guess), \"new_document\": if the client mentions something that may need a tax document and fits none of those keys (an inheritance, a home sale, gambling winnings, foreign income), a few plain words naming that document, else null, \"memory\": one short lasting fact useful for collecting their documents (travel dates, who holds the paperwork, best time to reach them) or null, \"staff_reply\": if scope is not documents, a short reply the preparer could send, friendly, offering to discuss and giving no tax advice, else null}. Use question for anything asking for tax advice or needing a person. Documents still needed: " + JSON.stringify(items) + "\nMessage: " + JSON.stringify(text)
      : "You read emails from a tax client to their accounting firm's document-collection assistant. The attachments are handled separately; read only the note. Answer with JSON only: {\"items\": [{\"item_id\": id from the list, \"status\": \"later\" or \"none\", \"days\": number or null}] for each still-needed document the note says is coming later or that the client does not have, \"question\": true if the note asks something a person must answer, \"summary\": a plain summary in under 15 words, \"topics\": a list of zero or more of these keys, only for things the client says about their own year that the firm may not know yet: " + topicKeys() + " (empty list if none; never guess), \"new_document\": a few plain words naming a tax document the note suggests is needed and that fits none of those keys, else null}. Documents still needed: " + JSON.stringify(items) + "\nEmail note: " + JSON.stringify(text);
    try { let out; if (typeof sample.json === "function") out = await sample.json(prompt, { modelTier: "quick" }); else { const r = await sample(prompt, { modelTier: "quick" }); const m = /\{[\s\S]*\}/.exec(r.text || ""); out = m ? JSON.parse(m[0]) : null; } return out && typeof out === "object" ? out : null; } catch (x) { return null; }
