  const findClient = (n) => { const q = String(n || "").toLowerCase().trim(); return q ? S().clients.find((c) => (c.first + " " + c.last).toLowerCase() === q) || S().clients.find((c) => (c.first + " " + c.last).toLowerCase().includes(q)) || S().clients.find((c) => q.includes(c.last.toLowerCase())) : null; };
  const findItem = (e, name) => { const q = String(name || "").toLowerCase().replace(/[^a-z0-9 ]/g, ""); return T.itemsOf(e.id).find((i) => i.form.toLowerCase() === q.replace(/ /g, "")) || T.itemsOf(e.id).find((i) => q && (fname(i.form).toLowerCase().includes(q) || q.includes(fname(i.form).toLowerCase()) || (i.payer && q.includes(i.payer.toLowerCase())))); };
